import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Supplier;

public class StampedeProtectedCache<K, V> {
    private final ConcurrentHashMap<K, V> cache = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<K, ReentrantLock> locks = new ConcurrentHashMap<>();

    public V getOrCompute(K key, Supplier<V> dbFetcher) {
        V value = cache.get(key);
        if (value != null) {
            return value;
        }

        ReentrantLock lock = locks.computeIfAbsent(key, k -> new ReentrantLock());
        lock.lock();
        try {
            // Double-check locking idiom inside synchronized critical section
            value = cache.get(key);
            if (value != null) {
                return value;
            }
            value = dbFetcher.get();
            cache.put(key, value);
        } finally {
            lock.unlock();
            locks.remove(key, lock);
        }
        return value;
    }
}
